/// Base-6 stride between the six children of a node at each tree depth,
/// from `getNode` in `minecraft.ts`: `[1296+216+36+6+1, 216+36+6+1, 36+6+1,
/// 6+1, 1]`.
const NODE_STEPS: [usize; 5] = [1555, 259, 43, 7, 1];

#[inline]
fn u64_as_i64(v: u64) -> i64 {
    v as i64
}

/// Squared distance contribution of one climate dimension against the range
/// `[min, max]`, `niduy`'s inner loop of `getDistance`:
///
/// ```ts
/// let a = intToUint64(np[i] - BIOME_PARAMS[idx][1]);
/// let b = intToUint64(BIOME_PARAMS[idx][0] - np[i]);
/// let d = uint64ToInt64(a) > 0 ? a : uint64ToInt64(b) > 0 ? b : 0n;
/// d = multiply64(d, d);
/// ```
#[inline]
fn axis_distance(np: i64, min: i64, max: i64) -> u64 {
    let a = (np - max) as u64; // positive when np is above the range
    let b = (min - np) as u64; // positive when np is below the range
    if u64_as_i64(a) > 0 {
        a
    } else if u64_as_i64(b) > 0 {
        b
    } else {
        0
    }
}

/// `getDistance(np, index)` from `minecraft.ts`.
#[inline]
fn get_distance(np: &[i32; 6], index: usize) -> u64 {
    let node = BIOME_TREE.get(index).copied().unwrap_or(0);
    let mut ds = 0u64;
    for i in 0..6 {
        let idx = ((node >> (i * 8)) & 0xff) as usize;
        let [min, max] = BIOME_PARAMS[idx];
        let d = axis_distance(np[i] as i64, min as i64, max as i64);
        ds = ds.wrapping_add(d.wrapping_mul(d));
    }
    ds
}

/// `getNode(np, idx, alt, ds, depth)` from `minecraft.ts`: nearest-neighbour
/// descent over the base-6 tree, pruning children whose distance no longer
/// improves on `dsx`.
fn get_node(np: &[i32; 6], idx: usize, alt: usize, ds: u64, depth: usize) -> usize {
    if depth >= 5 {
        return idx;
    }

    let mut dsx = ds;
    let mut depthx = depth;

    // do { if (depthx >= 5) throw; step = steps[depthx]; depthx++; }
    // while (idx + step >= BIOME_TREE.length)
    let step = loop {
        if depthx >= 5 {
            panic!("biome tree: invalid depth at index {idx}");
        }
        let step = NODE_STEPS[depthx];
        depthx += 1;
        if idx + step < BIOME_TREE.len() {
            break step;
        }
    };

    let node = BIOME_TREE[idx];
    let mut inner = (node >> 48) as usize;
    let mut leaf = alt;

    for _ in 0..6 {
        let inner_ds = get_distance(np, inner);
        if inner_ds < dsx {
            let leaf2 = get_node(np, inner, leaf, ds, depthx);
            let ds_leaf2 = if inner == leaf2 {
                inner_ds
            } else {
                get_distance(np, leaf2)
            };
            if ds_leaf2 < dsx {
                dsx = ds_leaf2;
                leaf = leaf2;
            }
        }

        inner += step;
        if inner >= BIOME_TREE.len() {
            break;
        }
    }

    leaf
}

#[inline]
fn is_java_biome_id(id: u8) -> bool {
    JAVA_BIOME_IDS.contains(&id)
}

/// `genOverworld(np)` from `minecraft.ts`: walk the tree and read the Java
/// biome id out of the winning leaf.
///
/// `np` is `[temperature, humidity, continentalness, erosion, depth,
/// weirdness]`, each scaled by 10000 (as `sampleBiomeNoise` builds it).
#[inline]
pub fn gen_overworld(np: &[i32; 6]) -> u8 {
    let idx = get_node(np, 0, 0, u64::MAX, 0);
    let node = BIOME_TREE[idx];
    let result = ((node >> 48) & 0xff) as u8;
    debug_assert!(
        is_java_biome_id(result),
        "biome tree returned an id not in BIOME: {result}"
    );
    result
}

/// Maps the Java biome id produced by [`gen_overworld`] onto Bedrock's
/// legacy biome-id space (the ids BDS and PocketMine put on the wire).
///
/// Most pre-1.18 ids are identical. The differences:
///
/// - Bedrock folds the four End biome ids (Java 40-43) into `the_end` (9);
///   its slots 40-49 are the modern oceans and bamboo jungle instead.
/// - Bedrock renumbered the oceans: `warm` 40, `deep_warm` 41, `lukewarm`
///   42, `deep_lukewarm` 43, `cold` 44, `deep_cold` 45, `frozen` 46,
///   `deep_frozen` 47 (Java used 44-50).
/// - Bamboo jungle moved from Java 168/169 to Bedrock 48/49.
/// - The 1.18 nether, cave and mountain biomes got Bedrock ids 178-191
///   (`soul_sand_valley` .. `mangrove_swamp`); Java numbers them 170-184
///   with a gap at 176.
///
/// Source of the Bedrock ids: PocketMine-MP's
/// `generated/data/bedrock/BiomeIds.php`.
#[inline]
pub fn java_to_bedrock(java: u8) -> u8 {
    match java {
        // End biomes -> Bedrock's single the_end (9); 40-49 are oceans there.
        40..=43 => 9,
        // Oceans (Java 44-50 -> Bedrock 40-47).
        44 => 40, // warm_ocean
        45 => 42, // lukewarm_ocean
        46 => 44, // cold_ocean
        47 => 41, // deep_warm_ocean
        48 => 43, // deep_lukewarm_ocean
        49 => 45, // deep_cold_ocean
        50 => 47, // deep_frozen_ocean
        10 => 46, // frozen_ocean (Bedrock keeps 10 only as a legacy alias)
        // Bamboo jungle.
        168 => 48,
        169 => 49,
        // 1.18 nether / cave / mountain biomes.
        170 => 178, // soul_sand_valley
        171 => 179, // crimson_forest
        172 => 180, // warped_forest
        173 => 181, // basalt_deltas
        174 => 188, // dripstone_caves
        175 => 187, // lush_caves
        177 => 186, // meadow
        178 => 185, // grove
        179 => 184, // snowy_slopes
        180 => 182, // jagged_peaks
        181 => 183, // frozen_peaks
        182 => 189, // stony_peaks
        183 => 190, // deep_dark
        184 => 191, // mangrove_swamp
        other => other,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Smoke test over a grid of climate values: the tree must terminate and
    /// always yield a biome id from the `BIOME` table.
    #[test]
    fn gen_overworld_always_returns_a_biome() {
        let mut count = 0;
        for t in (-120..=120).step_by(13) {
            for h in (-120..=120).step_by(29) {
                for c in (-120..=120).step_by(11) {
                    for e in (-120..=120).step_by(37) {
                        for w in (-120..=120).step_by(41) {
                            let np = [
                                t * 100, h * 100, c * 100, e * 100, 4800, w * 100,
                            ];
                            let id = gen_overworld(&np);
                            assert!(is_java_biome_id(id), "got invalid id {id} for np {np:?}");
                            count += 1;
                        }
                    }
                }
            }
        }
        assert!(count > 10_000);
    }

    #[test]
    fn tree_shape_matches_niduy() {
        // 9112 nodes, 7593 of them leaves (0xff marker), child indices at
        // most 9109 — as measured against const.ts.
        let leaves = BIOME_TREE.iter().filter(|n| (**n >> 56) == 0xff).count();
        assert_eq!(BIOME_TREE.len(), 9112);
        assert_eq!(leaves, 7593);
        let max_child = BIOME_TREE
            .iter()
            .filter(|n| (**n >> 56) != 0xff)
            .map(|n| (n >> 48) as usize)
            .max()
            .unwrap();
        assert_eq!(max_child, 9109);
        // All six parameter indices of every node must be in range.
        for n in BIOME_TREE.iter() {
            for i in 0..6 {
                let idx = ((n >> (i * 8)) & 0xff) as usize;
                assert!(idx < BIOME_PARAMS.len(), "param idx {idx} out of range");
            }
        }
    }

    #[test]
    fn java_to_bedrock_maps_the_oceans() {
        assert_eq!(java_to_bedrock(0), 0);
        assert_eq!(java_to_bedrock(44), 40);
        assert_eq!(java_to_bedrock(45), 42);
        assert_eq!(java_to_bedrock(48), 43);
        assert_eq!(java_to_bedrock(50), 47);
        assert_eq!(java_to_bedrock(10), 46);
        assert_eq!(java_to_bedrock(168), 48);
        assert_eq!(java_to_bedrock(184), 191);
        assert_eq!(java_to_bedrock(1), 1);
    }
}
